CREATE TABLE literature_identities(workspace_id TEXT NOT NULL,id TEXT NOT NULL,identity_key TEXT NOT NULL,doi TEXT,current_revision_id TEXT,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,identity_key));
CREATE TABLE literature_metadata_revisions(workspace_id TEXT NOT NULL,id TEXT NOT NULL,literature_id TEXT NOT NULL,metadata_json TEXT NOT NULL,content_sha256 TEXT NOT NULL,retrieved_at TEXT NOT NULL,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,literature_id,content_sha256),FOREIGN KEY(workspace_id,literature_id) REFERENCES literature_identities(workspace_id,id));
CREATE INDEX idx_literature_metadata ON literature_metadata_revisions(workspace_id,literature_id,retrieved_at DESC,id);
CREATE TABLE literature_fulltext_links(workspace_id TEXT NOT NULL,literature_id TEXT NOT NULL,document_id TEXT NOT NULL,version_id TEXT NOT NULL,rights_basis TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,literature_id,document_id,version_id),FOREIGN KEY(workspace_id,literature_id) REFERENCES literature_identities(workspace_id,id));
CREATE TABLE literature_provider_rate(workspace_id TEXT NOT NULL,provider TEXT NOT NULL,last_request_ms INTEGER NOT NULL,PRIMARY KEY(workspace_id,provider));
CREATE TABLE literature_reviewed_evidence(workspace_id TEXT NOT NULL,id TEXT NOT NULL,project_id TEXT NOT NULL,payload_json TEXT NOT NULL,content_sha256 TEXT NOT NULL,artifact_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,project_id,content_sha256),FOREIGN KEY(workspace_id,project_id) REFERENCES research_projects(workspace_id,id));
CREATE TRIGGER literature_revision_immutable BEFORE UPDATE ON literature_metadata_revisions BEGIN SELECT RAISE(ABORT,'immutable_literature_revision'); END;
CREATE TRIGGER literature_revision_no_delete BEFORE DELETE ON literature_metadata_revisions BEGIN SELECT RAISE(ABORT,'immutable_literature_revision'); END;
CREATE TRIGGER literature_evidence_immutable BEFORE UPDATE ON literature_reviewed_evidence BEGIN SELECT RAISE(ABORT,'immutable_literature_evidence'); END;
CREATE TRIGGER literature_evidence_no_delete BEFORE DELETE ON literature_reviewed_evidence BEGIN SELECT RAISE(ABORT,'immutable_literature_evidence'); END;
